## Property tests for the Issue #75 cross-stage persistence (CSP) policy.
##
## The residual (staging/gen_elabo_full.nim) is generated by
## staging/gen_direct_elabo_full.nim, which may only emit present-stage names
## declared in the csp registry via lift(). These tests check the policy's
## invariants on the generated residual:
##   1. every declared ref is used at least once (no dead declarations);
##   2. the residual's import block equals the registry-derived set;
##   3. every declared qualified name appears only spelled qualified
##      (no bare leakage);
##   4. freeVars(residual) ⊆ {Nim keywords, residual locals, residual-defined
##      names, declared unqualified names, import module names} — i.e. no
##      scope extrusion: nothing undeclared crosses the stage boundary.

import strutils
import sequtils
import sets
import csp
import staging/gen_direct_elabo_full

let residual = genResidual()

# --- 1. no dead declarations ------------------------------------------------
let unused = cspUnused()
doAssert unused.len == 0, "unused CSP declarations: " & unused.join(", ")
echo "ok: all ", cspRegistry.len, " declared CSP refs are used"

# --- helpers ----------------------------------------------------------------
type Tok = object
  text: string
  afterDot: bool

proc stripNoise(src: string): string =
  ## Replace string literals and comments with spaces (keep newlines).
  result = newStringOfCap(src.len)
  var i = 0
  while i < src.len:
    let c = src[i]
    if c == '"':
      result.add ' '
      inc i
      while i < src.len and src[i] != '"':
        if src[i] == '\\' and i + 1 < src.len:
          result.add "  "; i += 2
        else:
          result.add(if src[i] == '\n': '\n' else: ' ')
          inc i
      if i < src.len: result.add ' '; inc i
    elif c == '#':
      while i < src.len and src[i] != '\n':
        result.add ' '; inc i
    else:
      result.add c; inc i

proc tokenize(src: string): seq[Tok] =
  let clean = stripNoise(src)
  var j = 0
  while j < clean.len:
    let c = clean[j]
    if c.isAlphaAscii or c == '_':
      var k = j
      while k < clean.len and
          (clean[k].isAlphaNumeric or clean[k] in {'_', '\''}): inc k
      let t = clean[j ..< k]
      var p = j - 1
      while p >= 0 and clean[p] in {' ', '\t', '\n', '\r'}: dec p
      result.add Tok(text: t, afterDot: p >= 0 and clean[p] == '.')
      j = k
    else: inc j

let toks = tokenize(residual)

# --- 2. import block == registry-derived set ---------------------------------
var importLines: seq[string] = @[]
var seenNonImport = false
for line in residual.splitLines():
  let s = line.strip()
  if s.startsWith("import "):
    doAssert not seenNonImport, "import after non-import line: " & line
    importLines.add s[7 .. ^1].strip()
  elif s.len > 0 and not s.startsWith("##"):
    seenNonImport = true
let wantImports = cspImports()
doAssert importLines.len == wantImports.len and
         importLines.toHashSet == wantImports.toHashSet,
  "residual imports " & $importLines & " != registry imports " & $wantImports
echo "ok: import block matches registry (", importLines.join(", "), ")"

# --- 3. no bare leakage of qualified names ------------------------------------
for r in cspRegistry:
  if not r.qualified: continue
  for t in toks:
    doAssert not (t.text == r.name and not t.afterDot),
      "bare persistent name leaks into residual: " & r.name &
      " (must be spelled " & r.module & "." & r.name & ")"
echo "ok: all qualified persistent names spelled qualified (no bare leakage)"

# --- 4. freeVars(residual) is declared ----------------------------------------
const nimKeywords = ["addr", "and", "as", "asm", "bind", "block", "break",
  "case", "cast", "concept", "const", "continue", "converter", "defer",
  "discard", "distinct", "div", "do", "elif", "else", "end", "enum", "except",
  "export", "finally", "for", "from", "func", "if", "import", "in",
  "interface", "is", "isnot", "iterator", "let", "macro", "method", "mixin",
  "mod", "not", "notin", "of", "or", "out", "proc", "pure", "raise", "ref",
  "return", "shl", "shr", "static", "template", "try", "tuple", "type",
  "using", "var", "when", "while", "xor", "yield",
  "true", "false", "nil"]

var allowed = nimKeywords.toHashSet
# declared unqualified names (types, enum ctors, ambient stdlib)
for r in cspRegistry:
  if not r.qualified: allowed.incl r.name
# import module names
for m in importLines: allowed.incl m
# residual-defined procs/types: `proc name`, `type name`
for line in residual.splitLines():
  let s = line.strip()
  for kw in ["proc ", "type ", "iterator ", "template ", "macro "]:
    if s.startsWith(kw):
      var name = s[kw.len .. ^1]
      let cut = name.find({' ', '*', '(', '[', ':'})
      if cut >= 0: name = name[0 ..< cut]
      allowed.incl name
      break
# locals: proc params + let/var bindings + tuple field names
for line in residual.splitLines():
  let s = line.strip()
  if s.startsWith("proc "):
    let lp = s.find('('); let rp = s.find(')')
    if lp >= 0 and rp > lp:
      for p in s[lp+1 ..< rp].split(','):
        let nm = p.strip().split({' ', ':', '='})[0]
        if nm.len > 0 and nm[0].isAlphaAscii: allowed.incl nm
  elif s.startsWith("let ") or s.startsWith("var "):
    let rest = s[4 .. ^1]
    for chunk in rest.split(','):
      let nm = chunk.strip().split({' ', ':', '='})[0]
      if nm.len > 0 and nm[0].isAlphaAscii: allowed.incl nm
  if "tuple[" in s:
    let ts = s.find("tuple[")
    var depth = 0; var k = ts + 6; var cur = ""
    while k < s.len:
      if s[k] == '[': inc depth
      elif s[k] == ']':
        if depth == 0: break
        dec depth
      elif s[k] in {',', ':'} and depth == 0:
        let nm = cur.strip()
        if nm.len > 0 and nm[0].isAlphaAscii: allowed.incl nm
        cur = ""
        inc k
        continue
      else: cur.add s[k]
      inc k

var bad: seq[string] = @[]
for t in toks:
  if t.afterDot: continue            # field access / qualified tail
  if t.text notin allowed and t.text notin bad: bad.add t.text
doAssert bad.len == 0, "undeclared free identifiers in residual: " & bad.join(", ")
echo "ok: freeVars(residual) ⊆ declared (", toks.len, " tokens checked)"
echo "ALL CSP POLICY CHECKS PASSED"
